//! Platform-neutral Noise identity material.
//!
//! The private key is generated by the same Noise implementation used by the
//! TCP channel. Persistence is intentionally delegated to a platform key store.

use snow::{params::NoiseParams, Builder};
use std::fmt;
use zeroize::Zeroize;

const PROTOCOL: &str = "Noise_XX_25519_ChaChaPoly_SHA256";

#[derive(Debug)]
pub enum NoiseIdentityError {
    KeyGeneration(snow::Error),
}
impl fmt::Display for NoiseIdentityError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::KeyGeneration(error) => write!(f, "Could not generate Noise identity: {error}"),
        }
    }
}
impl std::error::Error for NoiseIdentityError {}

/// An X25519 static identity for Noise XX.
///
/// Private bytes are never exposed through a getter. Use `with_private_key`
/// only at the narrow boundary that creates a Noise session. The secret is
/// zeroized when this value is dropped. Callers must persist it using an
/// operating-system protected key store before advertising its public key.
pub struct NoiseIdentity {
    private_key: [u8; 32],
    public_key: [u8; 32],
}

impl NoiseIdentity {
    pub fn generate() -> Result<Self, NoiseIdentityError> {
        let params: NoiseParams = PROTOCOL.parse().expect("fixed Noise suite is valid");
        let pair = Builder::new(params)
            .generate_keypair()
            .map_err(NoiseIdentityError::KeyGeneration)?;
        let private_key: [u8; 32] = pair.private.try_into()
            .map_err(|_| NoiseIdentityError::KeyGeneration(snow::Error::Input))?;
        let public_key: [u8; 32] = pair.public.try_into()
            .map_err(|_| NoiseIdentityError::KeyGeneration(snow::Error::Input))?;
        Ok(Self { private_key, public_key })
    }

    pub fn public_key(&self) -> &[u8; 32] {
        &self.public_key
    }

    /// Restricts private-key access to a closure and zeroizes temporary copies.
    pub fn with_private_key<T>(&self, operation: impl FnOnce(&[u8; 32]) -> T) -> T {
        operation(&self.private_key)
    }
}

impl Drop for NoiseIdentity {
    fn drop(&mut self) {
        self.private_key.zeroize();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generates_distinct_valid_noise_static_keys() {
        let first = NoiseIdentity::generate().unwrap();
        let second = NoiseIdentity::generate().unwrap();
        assert_eq!(first.public_key().len(), 32);
        assert_eq!(second.public_key().len(), 32);
        assert_ne!(first.public_key(), second.public_key());
        first.with_private_key(|key| assert_eq!(key.len(), 32));
    }
}
